"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["36598"],{3283(e,t,n){n.d(t,{Ay:()=>r,RM:()=>i});var s=n(74848),o=n(28453);let i=[];function a(e){let t={a:"a",blockquote:"blockquote",h1:"h1",header:"header",li:"li",ol:"ol",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"some-questions-about-this-blog",children:"Some Questions About This Blog"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2007/9/20 19:55:37"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"More and more people are coming here. Recently, daily page views have consistently been around 60,000 to 80,000, which proves that this place is no longer just this ID's private garden. So there are some things I'd like to discuss with everyone:"}),"\n",(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Some people feel that the red color used for the afternoon market commentary is hard on the eyes. But using black or green, others feel it's unlucky. So, does anyone have a better suggestion? This ID doesn't care either way."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:["A reader has created a Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n technical analysis website at ",(0,s.jsx)(t.a,{href:"http://www.chzhshch.net/",children:"http://www.chzhshch.net/"}),". This ID just took a look \u2014 nearly 4,000 people have already registered. Therefore, this ID must state a position. First, this ID does not oppose any non-profit website of this kind, because if there's a better platform for discussing technical issues, it also helps create an environment for mutual improvement. Second, to avoid any appearance of impropriety, this ID will not be involved in any matters of such websites. Third, whether here or on websites, these are all just aids. What ultimately matters must be rooted in yourself \u2014 that is the most critical point."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Since the image upload quota here is too small, and uploading every segment every day quickly eats up the space, I've seen suggestions to use timestamps (or numbering) instead. This ID thinks that's feasible. From now on, unless there's something special, I'll use this method, but I'll upload actual chart images at least once per week."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"This place is open. Anyone can come and say anything. If this place lets you vent some negative emotions and thereby improves your physical and mental health, that's also a great thing. So come here and take what you need. There's no need for pointless quarreling. Quarreling hurts the body \u2014 unnecessary. Of course, if you find that arguing is invigorating and after a good fight your inner power surges to the point of riding clouds and mist, then by all means continue. This ID has no objections."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Some people seem very curious about this ID's private matters. That's fine \u2014 people are naturally curious. Who this ID is \u2014 everyone will eventually know, and then of course you'll know naturally. However, once you know, perhaps the blog's karmic connection will have reached its end, and there may be a different kind of connection. Connections gather and scatter \u2014 let each be resolved in its own way."}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"This afternoon, this ID merely used a specific example to tell everyone how pointless prediction is. I was absolutely not telling everyone that tomorrow will be red flags flying everywhere. Everything must become a habit of reading charts and operating accordingly. I hear that some so-called predictors have already started backtracking. Actually, that's the most incompetent kind. For example, with time-window predictions, there's still the question of a window opening and closing \u2014 plus or minus three days, all within range. From a purely analytical perspective, the current situation is simply: (1) yesterday's dive may have already fulfilled that time window; (2) the next three days are what's truly critical. But from the perspective of this ID's theory, none of this needs prediction at all \u2014 just let the market tell you."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"If one must talk about the influence of solar terms, generally around Mid-Autumn Festival there tend to be fluctuations. The most famous was that '94 one \u2014 probably all the moon's fault. All of this can only be used as reference. There's no need to take it seriously. What matters is the chart's signals."}),"\n",(0,s.jsx)(t.p,{children:"One sentence: when it rises, think about selling some; when it falls, think about buying some. That is the correct rhythm."}),"\n",(0,s.jsx)(t.p,{children:"Nothing more to write today. Going to watch football. Goodbye."})]})}function r(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(a,{...e})}):a(e)}},80450(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>d,frontMatter:()=>r,contentTitle:()=>l,toc:()=>c,assets:()=>h});var s=JSON.parse('{"id":"timeline/essays/somequestionsaboutthisblog","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/essays/somequestionsaboutthisblog.md","sourceDirName":"timeline/essays","slug":"/timeline/essays/somequestionsaboutthisblog","permalink":"/en/timeline/essays/somequestionsaboutthisblog","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"somequestionsaboutthisblog","title":"","hide_table_of_contents":true,"sidebar_label":"Some issues regarding the blog (2007/9/20 19:55:37)"},"sidebar":"timelineSidebar","previous":{"title":"Bears completely defeated: Predictors must be humiliated (2007/9/20 15:40:19)","permalink":"/en/timeline/economics/shortfail"},"next":{"title":"Suggestions on Sina\'s ad revenue sharing program (2007/9/21 8:36:58)","permalink":"/en/timeline/essays/aboutadsharing"}}'),o=n(74848),i=n(28453),a=n(3283);let r={id:"somequestionsaboutthisblog",title:"",hide_table_of_contents:!0,sidebar_label:"Some issues regarding the blog (2007/9/20 19:55:37)"},l,h={},c=[...a.RM];function u(e){return(0,o.jsx)(a.Ay,{})}function d(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var s=n(96540);let o={},i=s.createContext(o);function a(e){let t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);